css_variables:
:root {
  --color-primary: #1565C0;
  --color-secondary: #1E88E5;
  --color-accent: #10B981;
  --color-highlight: #EBF5FF;
  --color-bg: #FFFFFF;
  --color-text: #0F172A;
  --color-text-muted: #64748B;
  --color-border: #E5E7EB;
  --font-heading: 'Manrope', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-body: 'Inter', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-size-display: 56px;
  --font-size-h1: 40px;
  --font-size-h2: 30px;
  --font-size-h3: 24px;
  --font-size-h4: 18px;
  --font-size-body: 16px;
  --font-size-small: 12px;
  --font-weight-heading: 700;
  --font-weight-body: 400;
  --line-height-body: 1.7;
  --border-radius: 12px;
  --shadow-card: 0 2px 6px rgba(0,0,0,0.08), 0 6px 18px rgba(21,101,192,0.10);
}
